 {id:'BAG-0082',status:'Missing',location:'Check-in entry',camera:'CAM-01',events:[['12:01:10','Check-in entry','Bag registered'],['12:01:25','BELT-01','Departed checkpoint'],['12:02:10','Transfer junction','Expected arrival overdue; location unconfirmed']]},
 {id:'BAG-0083',status:'Moving',location:'Gate collection',camera:'CAM-03',events:[['12:00:42','Check-in entry','Bag registered'],['12:01:08','Transfer junction','Checkpoint confirmed'],['12:01:39','Gate collection','Checkpoint confirmed']]},
